with valid as (select *, upper(channel) as channel_upper, initcap(trim(promo_code)) as promo_code_title, coalesce(channel, 'DIRECT') as channel_filled from promotions where starts_on > to_date('2023-03-27') and starts_on <= '2025-10-01') select id, promo_code, starts_on, ends_on, percent_rank() over (partition by promo_code order by discount_pct desc) as discount_pct_percent_rank, last_value(channel, true) over (order by discount_pct, id rows between unbounded preceding and current row) as last_known_channel from valid
